insert into public.exercises (id, name_en, name_ar, muscle, muscles, equipment, level, category, steps_en, steps_ar, images, machines, timed, rank, search)
  values ('machinelateral', 'Machine lateral raise', 'رفرفة جانبي جهاز', 'Shoulders', array['shoulders'], 'Machine', 'beginner', 'strength', array['Sit on the lateral raise machine with the pads on the outside of your upper arms.', 'Raise your arms out to the sides until they reach shoulder height.', 'Lower slowly.']::text[], array['اجلس على جهاز الرفرفة والمساند على جنب ذراعك.', 'ارفع يدينك للجنب لين مستوى الكتف.', 'نزّل ببطء.']::text[], array['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Lateral_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Lateral_Raise/1.jpg']::text[], '[["Lateral raise machine", "جهاز الرفرفة الجانبي"]]'::jsonb, false, 0, 'machine lateral raise رفرفة جانبي جهاز machine lateral raise side رفرفه جانبي جهاز')
  on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, steps_en = excluded.steps_en, steps_ar = excluded.steps_ar, images = excluded.images, machines = excluded.machines, rank = 0, search = excluded.search;

